-- Lengthen the verse-of-the-day cycle from 8 to 537 verses (King James Version,
-- public domain) so every day of the year shows a different verse. The first 8
-- rows are unchanged; get_verse_of_the_day adapts to the active count.
-- Mirrors supabase/functions/_shared/dailyVerses.json, which must stay in the same order.
ON CONFLICT (sort_order) DO UPDATE SET reference = EXCLUDED.reference, verse_text = EXCLUDED.verse_text, active = true;
