INSERT INTO public.daily_verses (reference, verse_text, sort_order) VALUES
  ('2 Thessalonians 2:16-17', 'Now our Lord Jesus Christ himself, and God, even our Father, which hath loved us, and hath given us everlasting consolation and good hope through grace, Comfort your hearts, and stablish you in every good word and work.', 9),
  ('Psalm 139:23-24', 'Search me, O God, and know my heart: try me, and know my thoughts: And see if there be any wicked way in me, and lead me in the way everlasting.', 10),
  ('Job 33:4', 'The Spirit of God hath made me, and the breath of the Almighty hath given me life.', 11),
  ('Psalm 48:14', 'For this God is our God for ever and ever: he will be our guide even unto death.', 12),
  ('1 John 4:11', 'Beloved, if God so loved us, we ought also to love one another.', 13),
  ('Psalm 77:11', 'I will remember the works of the Lord: surely I will remember thy wonders of old.', 14),
  ('1 John 2:17', 'And the world passeth away, and the lust thereof: but he that doeth the will of God abideth for ever.', 15),
  ('Psalm 90:1-2', 'Lord, thou hast been our dwelling place in all generations. Before the mountains were brought forth, or ever thou hadst formed the earth and the world, even from everlasting to everlasting, thou art God.', 16),
  ('Isaiah 52:7', 'How beautiful upon the mountains are the feet of him that bringeth good tidings, that publisheth peace; that bringeth good tidings of good, that publisheth salvation; that saith unto Zion, Thy God reigneth!', 17),
  ('Psalm 108:3-4', 'I will praise thee, O Lord, among the people: and I will sing praises unto thee among the nations. For thy mercy is great above the heavens: and thy truth reacheth unto the clouds.', 18),
  ('James 1:12', 'Blessed is the man that endureth temptation: for when he is tried, he shall receive the crown of life, which the Lord hath promised to them that love him.', 19),
  ('Psalm 33:20-22', 'Our soul waiteth for the Lord: he is our help and our shield. For our heart shall rejoice in him, because we have trusted in his holy name. Let thy mercy, O Lord, be upon us, according as we hope in thee.', 20),
  ('2 Corinthians 1:3-4', 'Blessed be God, even the Father of our Lord Jesus Christ, the Father of mercies, and the God of all comfort; Who comforteth us in all our tribulation, that we may be able to comfort them which are in any trouble, by the comfort wherewith we ourselves are comforted of God.', 21),
  ('Psalm 56:3', 'What time I am afraid, I will trust in thee.', 22),
  ('John 13:34-35', 'A new commandment I give unto you, That ye love one another; as I have loved you, that ye also love one another. By this shall all men know that ye are my disciples, if ye have love one to another.', 23),
  ('Isaiah 1:18', 'Come now, and let us reason together, saith the Lord: though your sins be as scarlet, they shall be as white as snow; though they be red like crimson, they shall be as wool.', 24),
  ('John 20:21', 'Then said Jesus to them again, Peace be unto you: as my Father hath sent me, even so send I you.', 25),
  ('Psalm 23:4', 'Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me.', 26),
  ('John 6:35', 'And Jesus said unto them, I am the bread of life: he that cometh to me shall never hunger; and he that believeth on me shall never thirst.', 27),
  ('Psalm 69:30', 'I will praise the name of God with a song, and will magnify him with thanksgiving.', 28),
  ('Colossians 3:16', 'Let the word of Christ dwell in you richly in all wisdom; teaching and admonishing one another in psalms and hymns and spiritual songs, singing with grace in your hearts to the Lord.', 29),
  ('Lamentations 3:26', 'It is good that a man should both hope and quietly wait for the salvation of the Lord.', 30),
  ('Philippians 4:4', 'Rejoice in the Lord alway: and again I say, Rejoice.', 31),
  ('2 Chronicles 7:14', 'If my people, which are called by my name, shall humble themselves, and pray, and seek my face, and turn from their wicked ways; then will I hear from heaven, and will forgive their sin, and will heal their land.', 32),
  ('Matthew 5:7', 'Blessed are the merciful: for they shall obtain mercy.', 33),
  ('1 Chronicles 16:34', 'O give thanks unto the Lord; for he is good; for his mercy endureth for ever.', 34),
  ('Romans 8:15', 'For ye have not received the spirit of bondage again to fear; but ye have received the Spirit of adoption, whereby we cry, Abba, Father.', 35),
  ('Psalm 57:1', 'Be merciful unto me, O God, be merciful unto me: for my soul trusteth in thee: yea, in the shadow of thy wings will I make my refuge, until these calamities be overpast.', 36),
  ('Matthew 6:26', 'Behold the fowls of the air: for they sow not, neither do they reap, nor gather into barns; yet your heavenly Father feedeth them. Are ye not much better than they?', 37),
  ('Isaiah 30:15', 'For thus saith the Lord God, the Holy One of Israel; In returning and rest shall ye be saved; in quietness and in confidence shall be your strength: and ye would not.', 38),
  ('Mark 1:15', 'And saying, The time is fulfilled, and the kingdom of God is at hand: repent ye, and believe the gospel.', 39),
  ('Proverbs 15:1', 'A soft answer turneth away wrath: but grievous words stir up anger.', 40),
  ('Luke 11:28', 'But he said, Yea rather, blessed are they that hear the word of God, and keep it.', 41),
  ('Isaiah 40:28', 'Hast thou not known? hast thou not heard, that the everlasting God, the Lord, the Creator of the ends of the earth, fainteth not, neither is weary? there is no searching of his understanding.', 42),
  ('Matthew 18:3', 'And said, Verily I say unto you, Except ye be converted, and become as little children, ye shall not enter into the kingdom of heaven.', 43),
  ('Psalm 111:10', 'The fear of the Lord is the beginning of wisdom: a good understanding have all they that do his commandments: his praise endureth for ever.', 44),
  ('Romans 10:9', 'That if thou shalt confess with thy mouth the Lord Jesus, and shalt believe in thine heart that God hath raised him from the dead, thou shalt be saved.', 45),
  ('Micah 7:18', 'Who is a God like unto thee, that pardoneth iniquity, and passeth by the transgression of the remnant of his heritage? he retaineth not his anger for ever, because he delighteth in mercy.', 46),
  ('1 Peter 2:24', 'Who his own self bare our sins in his own body on the tree, that we, being dead to sins, should live unto righteousness: by whose stripes ye were healed.', 47),
  ('Genesis 28:15', 'And, behold, I am with thee, and will keep thee in all places whither thou goest, and will bring thee again into this land; for I will not leave thee, until I have done that which I have spoken to thee of.', 48),
  ('Romans 8:18', 'For I reckon that the sufferings of this present time are not worthy to be compared with the glory which shall be revealed in us.', 49),
  ('Psalm 143:10', 'Teach me to do thy will; for thou art my God: thy spirit is good; lead me into the land of uprightness.', 50),
  ('John 14:18', 'I will not leave you comfortless: I will come to you.', 51),
  ('Isaiah 40:29', 'He giveth power to the faint; and to them that have no might he increaseth strength.', 52),
  ('Galatians 2:20', 'I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me: and the life which I now live in the flesh I live by the faith of the Son of God, who loved me, and gave himself for me.', 53),
  ('Psalm 27:4', 'One thing have I desired of the Lord, that will I seek after; that I may dwell in the house of the Lord all the days of my life, to behold the beauty of the Lord, and to enquire in his temple.', 54),
  ('Revelation 21:4', 'And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away.', 55),
  ('Isaiah 7:14', 'Therefore the Lord himself shall give you a sign; Behold, a virgin shall conceive, and bear a son, and shall call his name Immanuel.', 56),
  ('1 Corinthians 15:57', 'But thanks be to God, which giveth us the victory through our Lord Jesus Christ.', 57),
  ('Isaiah 9:6', 'For unto us a child is born, unto us a son is given: and the government shall be upon his shoulder: and his name shall be called Wonderful, Counsellor, The mighty God, The everlasting Father, The Prince of Peace.', 58),
  ('Luke 1:46-47', 'And Mary said, My soul doth magnify the Lord, And my spirit hath rejoiced in God my Saviour.', 59),
  ('Ecclesiastes 3:11', 'He hath made every thing beautiful in his time: also he hath set the world in their heart, so that no man can find out the work that God maketh from the beginning to the end.', 60),
  ('Galatians 5:1', 'Stand fast therefore in the liberty wherewith Christ hath made us free, and be not entangled again with the yoke of bondage.', 61),
  ('Psalm 50:15', 'And call upon me in the day of trouble: I will deliver thee, and thou shalt glorify me.', 62),
  ('Luke 2:10-11', 'And the angel said unto them, Fear not: for, behold, I bring you good tidings of great joy, which shall be to all people. For unto you is born this day in the city of David a Saviour, which is Christ the Lord.', 63),
  ('Psalm 127:1', 'Except the Lord build the house, they labour in vain that build it: except the Lord keep the city, the watchman waketh but in vain.', 64),
  ('Romans 1:16', 'For I am not ashamed of the gospel of Christ: for it is the power of God unto salvation to every one that believeth; to the Jew first, and also to the Greek.', 65),
  ('Psalm 47:1', 'O clap your hands, all ye people; shout unto God with the voice of triumph.', 66),
  ('Romans 10:17', 'So then faith cometh by hearing, and hearing by the word of God.', 67),
  ('Hosea 14:4', 'I will heal their backsliding, I will love them freely: for mine anger is turned away from him.', 68),
  ('Philippians 2:3', 'Let nothing be done through strife or vainglory; but in lowliness of mind let each esteem other better than themselves.', 69),
  ('Psalm 32:7', 'Thou art my hiding place; thou shalt preserve me from trouble; thou shalt compass me about with songs of deliverance. Selah.', 70),
  ('Luke 9:23', 'And he said to them all, If any man will come after me, let him deny himself, and take up his cross daily, and follow me.', 71),
  ('Isaiah 44:22', 'I have blotted out, as a thick cloud, thy transgressions, and, as a cloud, thy sins: return unto me; for I have redeemed thee.', 72),
  ('Matthew 11:29-30', 'Take my yoke upon you, and learn of me; for I am meek and lowly in heart: and ye shall find rest unto your souls. For my yoke is easy, and my burden is light.', 73),
  ('Psalm 130:5', 'I wait for the Lord, my soul doth wait, and in his word do I hope.', 74),
  ('2 Corinthians 5:17', 'Therefore if any man be in Christ, he is a new creature: old things are passed away; behold, all things are become new.', 75),
  ('Isaiah 40:31', 'But they that wait upon the Lord shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint.', 76),
  ('John 16:33', 'These things I have spoken unto you, that in me ye might have peace. In the world ye shall have tribulation: but be of good cheer; I have overcome the world.', 77),
  ('Psalm 30:5', 'For his anger endureth but a moment; in his favour is life: weeping may endure for a night, but joy cometh in the morning.', 78),
  ('Matthew 5:3', 'Blessed are the poor in spirit: for theirs is the kingdom of heaven.', 79),
  ('Psalm 40:1-2', 'I waited patiently for the Lord; and he inclined unto me, and heard my cry. He brought me up also out of an horrible pit, out of the miry clay, and set my feet upon a rock, and established my goings.', 80),
  ('John 1:14', 'And the Word was made flesh, and dwelt among us, (and we beheld his glory, the glory as of the only begotten of the Father,) full of grace and truth.', 81),
  ('Psalm 54:4', 'Behold, God is mine helper: the Lord is with them that uphold my soul.', 82),
  ('John 6:37', 'All that the Father giveth me shall come to me; and him that cometh to me I will in no wise cast out.', 83),
  ('Isaiah 49:16', 'Behold, I have graven thee upon the palms of my hands; thy walls are continually before me.', 84),
  ('1 Corinthians 1:18', 'For the preaching of the cross is to them that perish foolishness; but unto us which are saved it is the power of God.', 85),
  ('Psalm 89:1', 'I will sing of the mercies of the Lord for ever: with my mouth will I make known thy faithfulness to all generations.', 86),
  ('Revelation 22:13', 'I am Alpha and Omega, the beginning and the end, the first and the last.', 87),
  ('Psalm 65:11', 'Thou crownest the year with thy goodness; and thy paths drop fatness.', 88),
  ('John 10:10', 'The thief cometh not, but for to steal, and to kill, and to destroy: I am come that they might have life, and that they might have it more abundantly.', 89),
  ('Psalm 112:7', 'He shall not be afraid of evil tidings: his heart is fixed, trusting in the Lord.', 90),
  ('Mark 11:24', 'Therefore I say unto you, What things soever ye desire, when ye pray, believe that ye receive them, and ye shall have them.', 91),
  ('Psalm 107:1', 'O give thanks unto the Lord, for he is good: for his mercy endureth for ever.', 92),
  ('Mark 9:24', 'And straightway the father of the child cried out, and said with tears, Lord, I believe; help thou mine unbelief.', 93),
  ('Psalm 125:1', 'They that trust in the Lord shall be as mount Zion, which cannot be removed, but abideth for ever.', 94),
  ('Mark 9:23', 'Jesus said unto him, If thou canst believe, all things are possible to him that believeth.', 95),
  ('Psalm 117:1-2', 'O praise the Lord, all ye nations: praise him, all ye people. For his merciful kindness is great toward us: and the truth of the Lord endureth for ever. Praise ye the Lord.', 96),
  ('Luke 2:14', 'Glory to God in the highest, and on earth peace, good will toward men.', 97),
  ('Isaiah 53:5', 'But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed.', 98),
  ('1 Thessalonians 5:16-18', 'Rejoice evermore. Pray without ceasing. In every thing give thanks: for this is the will of God in Christ Jesus concerning you.', 99),
  ('Nahum 1:7', 'The Lord is good, a strong hold in the day of trouble; and he knoweth them that trust in him.', 100),
  ('James 1:17', 'Every good gift and every perfect gift is from above, and cometh down from the Father of lights, with whom is no variableness, neither shadow of turning.', 101),
  ('Joshua 23:14', 'And, behold, this day I am going the way of all the earth: and ye know in all your hearts and in all your souls, that not one thing hath failed of all the good things which the Lord your God spake concerning you; all are come to pass unto you, and not one thing hath failed thereof.', 102),
  ('2 Timothy 1:7', 'For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind.', 103),
  ('Psalm 85:10', 'Mercy and truth are met together; righteousness and peace have kissed each other.', 104),
  ('Luke 23:42', 'And he said unto Jesus, Lord, remember me when thou comest into thy kingdom.', 105),
  ('Nehemiah 8:10', 'Then he said unto them, Go your way, eat the fat, and drink the sweet, and send portions unto them for whom nothing is prepared: for this day is holy unto our Lord: neither be ye sorry; for the joy of the Lord is your strength.', 106),
  ('Romans 8:1', 'There is therefore now no condemnation to them which are in Christ Jesus, who walk not after the flesh, but after the Spirit.', 107),
  ('1 Samuel 16:7', 'But the Lord said unto Samuel, Look not on his countenance, or on the height of his stature; because I have refused him: for the Lord seeth not as man seeth; for man looketh on the outward appearance, but the Lord looketh on the heart.', 108),
  ('Romans 12:2', 'And be not conformed to this world: but be ye transformed by the renewing of your mind, that ye may prove what is that good, and acceptable, and perfect, will of God.', 109),
  ('Psalm 119:68', 'Thou art good, and doest good; teach me thy statutes.', 110),
  ('Luke 17:21', 'Neither shall they say, Lo here! or, lo there! for, behold, the kingdom of God is within you.', 111),
  ('Psalm 145:3', 'Great is the Lord, and greatly to be praised; and his greatness is unsearchable.', 112),
  ('1 Corinthians 10:13', 'There hath no temptation taken you but such as is common to man: but God is faithful, who will not suffer you to be tempted above that ye are able; but will with the temptation also make a way to escape, that ye may be able to bear it.', 113),
  ('Psalm 57:10', 'For thy mercy is great unto the heavens, and thy truth unto the clouds.', 114),
  ('John 10:11', 'I am the good shepherd: the good shepherd giveth his life for the sheep.', 115),
  ('Isaiah 30:21', 'And thine ears shall hear a word behind thee, saying, This is the way, walk ye in it, when ye turn to the right hand, and when ye turn to the left.', 116),
  ('1 John 4:18', 'There is no fear in love; but perfect love casteth out fear: because fear hath torment. He that feareth is not made perfect in love.', 117),
  ('2 Chronicles 20:15', 'And he said, Hearken ye, all Judah, and ye inhabitants of Jerusalem, and thou king Jehoshaphat, Thus saith the Lord unto you, Be not afraid nor dismayed by reason of this great multitude; for the battle is not yours, but God’s.', 118),
  ('James 4:10', 'Humble yourselves in the sight of the Lord, and he shall lift you up.', 119),
  ('Psalm 149:4', 'For the Lord taketh pleasure in his people: he will beautify the meek with salvation.', 120),
  ('1 John 4:4', 'Ye are of God, little children, and have overcome them: because greater is he that is in you, than he that is in the world.', 121),
  ('Psalm 133:1', 'Behold, how good and how pleasant it is for brethren to dwell together in unity!', 122),
  ('John 8:12', 'Then spake Jesus again unto them, saying, I am the light of the world: he that followeth me shall not walk in darkness, but shall have the light of life.', 123),
  ('2 Samuel 22:29', 'For thou art my lamp, O Lord: and the Lord will lighten my darkness.', 124),
  ('James 3:17', 'But the wisdom that is from above is first pure, then peaceable, gentle, and easy to be intreated, full of mercy and good fruits, without partiality, and without hypocrisy.', 125),
  ('Psalm 34:18', 'The Lord is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit.', 126),
  ('Luke 6:38', 'Give, and it shall be given unto you; good measure, pressed down, and shaken together, and running over, shall men give into your bosom. For with the same measure that ye mete withal it shall be measured to you again.', 127),
  ('Psalm 147:11', 'The Lord taketh pleasure in them that fear him, in those that hope in his mercy.', 128),
  ('1 Corinthians 2:9', 'But as it is written, Eye hath not seen, nor ear heard, neither have entered into the heart of man, the things which God hath prepared for them that love him.', 129),
  ('Jeremiah 10:12', 'He hath made the earth by his power, he hath established the world by his wisdom, and hath stretched out the heavens by his discretion.', 130),
  ('John 12:46', 'I am come a light into the world, that whosoever believeth on me should not abide in darkness.', 131),
  ('Psalm 66:20', 'Blessed be God, which hath not turned away my prayer, nor his mercy from me.', 132),
  ('Acts 4:12', 'Neither is there salvation in any other: for there is none other name under heaven given among men, whereby we must be saved.', 133),
  ('Psalm 34:1', 'I will bless the Lord at all times: his praise shall continually be in my mouth.', 134),
  ('Galatians 3:28', 'There is neither Jew nor Greek, there is neither bond nor free, there is neither male nor female: for ye are all one in Christ Jesus.', 135),
  ('Psalm 22:3', 'But thou art holy, O thou that inhabitest the praises of Israel.', 136),
  ('Colossians 3:14', 'And above all these things put on charity, which is the bond of perfectness.', 137),
  ('Psalm 63:3', 'Because thy lovingkindness is better than life, my lips shall praise thee.', 138),
  ('Mark 12:31', 'And the second is like, namely this, Thou shalt love thy neighbour as thyself. There is none other commandment greater than these.', 139),
  ('Isaiah 54:10', 'For the mountains shall depart, and the hills be removed; but my kindness shall not depart from thee, neither shall the covenant of my peace be removed, saith the Lord that hath mercy on thee.', 140),
  ('Matthew 21:22', 'And all things, whatsoever ye shall ask in prayer, believing, ye shall receive.', 141),
  ('1 Samuel 2:2', 'There is none holy as the Lord: for there is none beside thee: neither is there any rock like our God.', 142),
  ('1 Timothy 1:15', 'This is a faithful saying, and worthy of all acceptation, that Christ Jesus came into the world to save sinners; of whom I am chief.', 143),
  ('Proverbs 17:17', 'A friend loveth at all times, and a brother is born for adversity.', 144),
  ('Philippians 4:19', 'But my God shall supply all your need according to his riches in glory by Christ Jesus.', 145),
  ('Habakkuk 3:19', 'The Lord God is my strength, and he will make my feet like hinds’ feet, and he will make me to walk upon mine high places. To the chief singer on my stringed instruments.', 146),
  ('Mark 10:27', 'And Jesus looking upon them saith, With men it is impossible, but not with God: for with God all things are possible.', 147),
  ('Psalm 119:50', 'This is my comfort in my affliction: for thy word hath quickened me.', 148),
  ('Ephesians 6:10', 'Finally, my brethren, be strong in the Lord, and in the power of his might.', 149),
  ('Isaiah 58:11', 'And the Lord shall guide thee continually, and satisfy thy soul in drought, and make fat thy bones: and thou shalt be like a watered garden, and like a spring of water, whose waters fail not.', 150),
  ('Matthew 6:21', 'For where your treasure is, there will your heart be also.', 151),
  ('Isaiah 32:17', 'And the work of righteousness shall be peace; and the effect of righteousness quietness and assurance for ever.', 152),
  ('Romans 15:7', 'Wherefore receive ye one another, as Christ also received us to the glory of God.', 153),
  ('Psalm 128:1', 'Blessed is every one that feareth the Lord; that walketh in his ways.', 154),
  ('John 10:27-28', 'My sheep hear my voice, and I know them, and they follow me: And I give unto them eternal life; and they shall never perish, neither shall any man pluck them out of my hand.', 155),
  ('Psalm 26:3', 'For thy lovingkindness is before mine eyes: and I have walked in thy truth.', 156),
  ('2 Peter 3:9', 'The Lord is not slack concerning his promise, as some men count slackness; but is longsuffering to us-ward, not willing that any should perish, but that all should come to repentance.', 157),
  ('Psalm 16:8', 'I have set the Lord always before me: because he is at my right hand, I shall not be moved.', 158),
  ('Romans 5:8', 'But God commendeth his love toward us, in that, while we were yet sinners, Christ died for us.', 159),
  ('Psalm 13:5-6', 'But I have trusted in thy mercy; my heart shall rejoice in thy salvation. I will sing unto the Lord, because he hath dealt bountifully with me.', 160),
  ('1 Corinthians 15:55', 'O death, where is thy sting? O grave, where is thy victory?', 161),
  ('Psalm 126:5', 'They that sow in tears shall reap in joy.', 162),
  ('Acts 20:35', 'I have shewed you all things, how that so labouring ye ought to support the weak, and to remember the words of the Lord Jesus, how he said, It is more blessed to give than to receive.', 163),
  ('Psalm 37:39', 'But the salvation of the righteous is of the Lord: he is their strength in the time of trouble.', 164),
  ('Luke 19:10', 'For the Son of man is come to seek and to save that which was lost.', 165),
  ('Isaiah 43:2', 'When thou passest through the waters, I will be with thee; and through the rivers, they shall not overflow thee: when thou walkest through the fire, thou shalt not be burned; neither shall the flame kindle upon thee.', 166),
  ('Matthew 28:20', 'Teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you alway, even unto the end of the world. Amen.', 167),
  ('Psalm 91:1-2', 'He that dwelleth in the secret place of the most High shall abide under the shadow of the Almighty. I will say of the Lord, He is my refuge and my fortress: my God; in him will I trust.', 168),
  ('Hebrews 13:16', 'But to do good and to communicate forget not: for with such sacrifices God is well pleased.', 169),
  ('Psalm 68:19', 'Blessed be the Lord, who daily loadeth us with benefits, even the God of our salvation. Selah.', 170),
  ('James 1:5', 'If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him.', 171),
  ('Psalm 84:10', 'For a day in thy courts is better than a thousand. I had rather be a doorkeeper in the house of my God, than to dwell in the tents of wickedness.', 172),
  ('2 Corinthians 4:6', 'For God, who commanded the light to shine out of darkness, hath shined in our hearts, to give the light of the knowledge of the glory of God in the face of Jesus Christ.', 173),
  ('Psalm 30:11-12', 'Thou hast turned for me my mourning into dancing: thou hast put off my sackcloth, and girded me with gladness; To the end that my glory may sing praise to thee, and not be silent. O Lord my God, I will give thanks unto thee for ever.', 174),
  ('Romans 8:31', 'What shall we then say to these things? If God be for us, who can be against us?', 175),
  ('Psalm 37:23-24', 'The steps of a good man are ordered by the Lord: and he delighteth in his way. Though he fall, he shall not be utterly cast down: for the Lord upholdeth him with his hand.', 176),
  ('1 John 1:7', 'But if we walk in the light, as he is in the light, we have fellowship one with another, and the blood of Jesus Christ his Son cleanseth us from all sin.', 177),
  ('Psalm 96:1', 'O sing unto the Lord a new song: sing unto the Lord, all the earth.', 178),
  ('Romans 12:21', 'Be not overcome of evil, but overcome evil with good.', 179),
  ('Ezekiel 36:26', 'A new heart also will I give you, and a new spirit will I put within you: and I will take away the stony heart out of your flesh, and I will give you an heart of flesh.', 180),
  ('Revelation 5:13', 'And every creature which is in heaven, and on the earth, and under the earth, and such as are in the sea, and all that are in them, heard I saying, Blessing, and honour, and glory, and power, be unto him that sitteth upon the throne, and unto the Lamb for ever and ever.', 181),
  ('Proverbs 15:13', 'A merry heart maketh a cheerful countenance: but by sorrow of the heart the spirit is broken.', 182),
  ('Philippians 2:13', 'For it is God which worketh in you both to will and to do of his good pleasure.', 183),
  ('Daniel 12:3', 'And they that be wise shall shine as the brightness of the firmament; and they that turn many to righteousness as the stars for ever and ever.', 184),
  ('Matthew 19:26', 'But Jesus beheld them, and said unto them, With men this is impossible; but with God all things are possible.', 185),
  ('Psalm 39:7', 'And now, Lord, what wait I for? my hope is in thee.', 186),
  ('Mark 6:31', 'And he said unto them, Come ye yourselves apart into a desert place, and rest a while: for there were many coming and going, and they had no leisure so much as to eat.', 187),
  ('Genesis 18:14', 'Is any thing too hard for the Lord? At the time appointed I will return unto thee, according to the time of life, and Sarah shall have a son.', 188),
  ('James 1:22', 'But be ye doers of the word, and not hearers only, deceiving your own selves.', 189),
  ('Psalm 90:17', 'And let the beauty of the Lord our God be upon us: and establish thou the work of our hands upon us; yea, the work of our hands establish thou it.', 190),
  ('Luke 18:27', 'And he said, The things which are impossible with men are possible with God.', 191),
  ('Isaiah 25:1', 'O Lord, thou art my God; I will exalt thee, I will praise thy name; for thou hast done wonderful things; thy counsels of old are faithfulness and truth.', 192),
  ('2 Thessalonians 3:3', 'But the Lord is faithful, who shall stablish you, and keep you from evil.', 193),
  ('Psalm 121:7-8', 'The Lord shall preserve thee from all evil: he shall preserve thy soul. The Lord shall preserve thy going out and thy coming in from this time forth, and even for evermore.', 194),
  ('Galatians 6:10', 'As we have therefore opportunity, let us do good unto all men, especially unto them who are of the household of faith.', 195),
